WITH source AS NOT MATERIALIZED (SELECT event.event_id,1 AS event_present,event.stream_id AS event_stream,event.sequence,event.type AS event_type,event.occurred_at,event.recorded_at,
    event.actor,event.client_id,event.correlation_id,event.causation_id,event.compensates_event_id,event.schema_version,
    event.payload AS public_body,secret.private_json AS private_body,
    secret.private_event_id,secret.owner_id AS private_owner,secret.project_id AS private_project,
    secret.document_id AS private_document,secret.redacted_at,event.sequence AS order_sequence,NULL AS member_source_stream,NULL AS member_source_sequence,
      NULL AS member_actor,NULL AS member_created FROM events event
      LEFT JOIN event_private_payloads secret ON secret.private_event_id=event.event_id WHERE event.stream_id=?), metadata AS NOT MATERIALIZED (SELECT CASE WHEN event_id IS NULL OR (typeof(event_id)='text' AND length(CAST(event_id AS BLOB))<=512) THEN event_id ELSE NULL END AS event_id,CASE WHEN event_stream IS NULL OR (typeof(event_stream)='text' AND length(CAST(event_stream AS BLOB))<=512) THEN event_stream ELSE NULL END AS event_stream,CASE WHEN event_type IS NULL OR (typeof(event_type)='text' AND length(CAST(event_type AS BLOB))<=512) THEN event_type ELSE NULL END AS event_type,CASE WHEN occurred_at IS NULL OR (typeof(occurred_at)='text' AND length(CAST(occurred_at AS BLOB))<=512) THEN occurred_at ELSE NULL END AS occurred_at,CASE WHEN recorded_at IS NULL OR (typeof(recorded_at)='text' AND length(CAST(recorded_at AS BLOB))<=512) THEN recorded_at ELSE NULL END AS recorded_at,CASE WHEN actor IS NULL OR (typeof(actor)='text' AND length(CAST(actor AS BLOB))<=512) THEN actor ELSE NULL END AS actor,CASE WHEN client_id IS NULL OR (typeof(client_id)='text' AND length(CAST(client_id AS BLOB))<=512) THEN client_id ELSE NULL END AS client_id,CASE WHEN correlation_id IS NULL OR (typeof(correlation_id)='text' AND length(CAST(correlation_id AS BLOB))<=512) THEN correlation_id ELSE NULL END AS correlation_id,CASE WHEN causation_id IS NULL OR (typeof(causation_id)='text' AND length(CAST(causation_id AS BLOB))<=512) THEN causation_id ELSE NULL END AS causation_id,CASE WHEN compensates_event_id IS NULL OR (typeof(compensates_event_id)='text' AND length(CAST(compensates_event_id AS BLOB))<=512) THEN compensates_event_id ELSE NULL END AS compensates_event_id,CASE WHEN private_event_id IS NULL OR (typeof(private_event_id)='text' AND length(CAST(private_event_id AS BLOB))<=512) THEN private_event_id ELSE NULL END AS private_event_id,CASE WHEN private_owner IS NULL OR (typeof(private_owner)='text' AND length(CAST(private_owner AS BLOB))<=512) THEN private_owner ELSE NULL END AS private_owner,CASE WHEN private_project IS NULL OR (typeof(private_project)='text' AND length(CAST(private_project AS BLOB))<=512) THEN private_project ELSE NULL END AS private_project,CASE WHEN private_document IS NULL OR (typeof(private_document)='text' AND length(CAST(private_document AS BLOB))<=512) THEN private_document ELSE NULL END AS private_document,CASE WHEN redacted_at IS NULL OR (typeof(redacted_at)='text' AND length(CAST(redacted_at AS BLOB))<=512) THEN redacted_at ELSE NULL END AS redacted_at,CASE WHEN member_source_stream IS NULL OR (typeof(member_source_stream)='text' AND length(CAST(member_source_stream AS BLOB))<=512) THEN member_source_stream ELSE NULL END AS member_source_stream,CASE WHEN member_actor IS NULL OR (typeof(member_actor)='text' AND length(CAST(member_actor AS BLOB))<=512) THEN member_actor ELSE NULL END AS member_actor,CASE WHEN member_created IS NULL OR (typeof(member_created)='text' AND length(CAST(member_created AS BLOB))<=512) THEN member_created ELSE NULL END AS member_created,
  event_present,sequence,order_sequence,schema_version,member_source_sequence,typeof(public_body) AS public_type,COALESCE(length(CAST(public_body AS BLOB)),0) AS public_bytes,
  typeof(private_body) AS private_type,COALESCE(length(CAST(private_body AS BLOB)),0) AS private_bytes,
  CASE WHEN (((((event_id IS NULL OR (typeof(event_id)='text' AND length(CAST(event_id AS BLOB))<=512)) AND (event_stream IS NULL OR (typeof(event_stream)='text' AND length(CAST(event_stream AS BLOB))<=512))) AND ((event_type IS NULL OR (typeof(event_type)='text' AND length(CAST(event_type AS BLOB))<=512)) AND (occurred_at IS NULL OR (typeof(occurred_at)='text' AND length(CAST(occurred_at AS BLOB))<=512)))) AND (((recorded_at IS NULL OR (typeof(recorded_at)='text' AND length(CAST(recorded_at AS BLOB))<=512)) AND (actor IS NULL OR (typeof(actor)='text' AND length(CAST(actor AS BLOB))<=512))) AND ((client_id IS NULL OR (typeof(client_id)='text' AND length(CAST(client_id AS BLOB))<=512)) AND ((correlation_id IS NULL OR (typeof(correlation_id)='text' AND length(CAST(correlation_id AS BLOB))<=512)) AND (causation_id IS NULL OR (typeof(causation_id)='text' AND length(CAST(causation_id AS BLOB))<=512)))))) AND ((((compensates_event_id IS NULL OR (typeof(compensates_event_id)='text' AND length(CAST(compensates_event_id AS BLOB))<=512)) AND (private_event_id IS NULL OR (typeof(private_event_id)='text' AND length(CAST(private_event_id AS BLOB))<=512))) AND ((private_owner IS NULL OR (typeof(private_owner)='text' AND length(CAST(private_owner AS BLOB))<=512)) AND (private_project IS NULL OR (typeof(private_project)='text' AND length(CAST(private_project AS BLOB))<=512)))) AND (((private_document IS NULL OR (typeof(private_document)='text' AND length(CAST(private_document AS BLOB))<=512)) AND (redacted_at IS NULL OR (typeof(redacted_at)='text' AND length(CAST(redacted_at AS BLOB))<=512))) AND ((member_source_stream IS NULL OR (typeof(member_source_stream)='text' AND length(CAST(member_source_stream AS BLOB))<=512)) AND ((member_actor IS NULL OR (typeof(member_actor)='text' AND length(CAST(member_actor AS BLOB))<=512)) AND (member_created IS NULL OR (typeof(member_created)='text' AND length(CAST(member_created AS BLOB))<=512))))))) THEN 1 ELSE 0 END AS metadata_valid FROM source), page AS MATERIALIZED
      (SELECT * FROM metadata WHERE order_sequence>? ORDER BY order_sequence LIMIT 256),
      budgeted AS (SELECT *,SUM(length(CAST(json_insert(json_object('event_id',event_id,'event_present',event_present,'event_stream',event_stream,'sequence',sequence,'order_sequence',order_sequence,'event_type',event_type,'occurred_at',occurred_at,'recorded_at',recorded_at,'actor',actor,'client_id',client_id,'correlation_id',correlation_id,'causation_id',causation_id,'compensates_event_id',compensates_event_id,'schema_version',schema_version,'private_event_id',private_event_id,'private_owner',private_owner),'$.private_project',private_project,'$.private_document',private_document,'$.redacted_at',redacted_at,'$.public_type',public_type,'$.public_bytes',public_bytes,'$.private_type',private_type,'$.private_bytes',private_bytes,'$.member_source_stream',member_source_stream,'$.member_source_sequence',member_source_sequence,'$.member_actor',member_actor,'$.member_created',member_created,'$.metadata_valid',metadata_valid) AS BLOB))+1) OVER (ORDER BY order_sequence) AS running_bytes FROM page)
      SELECT event_id,event_present,event_stream,sequence,order_sequence,event_type,occurred_at,recorded_at,actor,client_id,correlation_id,causation_id,compensates_event_id,schema_version,private_event_id,private_owner,private_project,private_document,redacted_at,public_type,public_bytes,private_type,private_bytes,member_source_stream,member_source_sequence,member_actor,member_created,metadata_valid FROM budgeted WHERE running_bytes<=524286 ORDER BY order_sequence